-- 자주 묻는 질문(faq_items) 정책 반영 (2026-11-13 [역할: policy])
-- 주인님 지시: 「업데이트 된 기능에 맞게 사용자 매뉴얼 내용을 쉽고 자세하게 보강해놓도록 해」
-- 대상 DB: AIMaster 운영 ref esgxyikcnnvmlhygjkth.
-- 이전 답(되돌리기용 백업):
--   33459321… 「사용하려는 서비스(OpenAI, Google Gemini, Perplexity 등) 공식 홈페이지에서 발급받습니다. 각 프로그램의 설정 페이지에 발급 방법 안내와 링크가 함께 제공됩니다.」
--   bdde5e9f… 「계정 보안을 위해 1계정 1세션으로 제한되어 있습니다. 새 기기·브라우저에서 로그인하면 기존 세션은 자동 로그아웃됩니다.」
--   f970654c… 「먼저 회원가입 후 원하는 프로그램을 구독하거나 개별 이용권을 받으시면 됩니다. 이후 각 프로그램의 설정 페이지에서 필요한 API 키와 외부 계정을 연동하면 바로 자동화를 시작할 수 있습니다.」
--   993b75b1… 「네. 각 프로그램마다 필요한 최소 등급이 설정되어 있고, 상위 등급은 하위 등급용 프로그램도 그대로 이용할 수 있습니다. 대시보드의 "내 구독"에서 현재 이용 가능한 프로그램 목록을 확인할 수 있습니다.」
-- 새로 넣은 줄 되돌리기: delete from public.faq_items where category = '저장공간 · 보관' or question = '핸드폰 번호를 꼭 등록해야 하나요?';

update public.faq_items set answer = '같은 계정으로 PC 1곳과 모바일(휴대폰·태블릿) 1곳에서 동시에 쓸 수 있습니다. 같은 종류의 기기에서 새로 로그인하면(예: 다른 PC) 그 종류의 이전 로그인만 자동으로 끊기고, 다른 종류의 기기는 그대로 유지됩니다. 로그아웃은 누른 그 기기(브라우저)에서만 됩니다. 계정을 여러 사람이 함께 쓰는 것은 허용되지 않습니다.'
where id = 'bdde5e9f-0c02-48aa-829d-78f1c6e894a2';

update public.faq_items set answer = '사용하려는 서비스(OpenAI, Anthropic Claude, Google Gemini, Perplexity 등)의 공식 홈페이지에서 본인 계정으로 발급받습니다. 처음이라면 위 메뉴 「API키생성|플랫폼연동」에서 서비스별 발급 방법을 화면 순서대로 따라 하실 수 있고, 각 프로그램의 「API키등록·플랫폼연동」 화면 아래에도 그 프로그램에 필요한 매뉴얼 버튼이 있습니다. 한 번 등록한 키는 다른 프로그램에서도 그대로 쓰이므로 프로그램마다 다시 넣지 않아도 됩니다.'
where id = '33459321-d96e-46d1-854c-360336480cdb';

update public.faq_items set answer = '첫째, 회원가입을 하고 핸드폰 번호를 등록합니다(번호가 없으면 프로그램을 쓸 수 없습니다). 둘째, 쓰고 싶은 프로그램을 고릅니다 — 「FREE」 표시가 있는 프로그램은 가입만 하면 바로 쓸 수 있고, 그 밖의 프로그램은 구독하거나 이용 기간을 받아야 합니다. 셋째, 그 프로그램의 「API키등록·플랫폼연동」 화면에서 본인 AI 키와 필요한 외부 계정(인스타그램·쓰레드·유튜브 등)을 연결합니다. 넷째, 프로그램의 「사용 매뉴얼」 순서대로 시작하면 됩니다.'
where id = 'f970654c-d194-487d-a5a9-0d3c4970cc11';

update public.faq_items set answer = '「FREE」 표시가 있는 프로그램은 등급과 상관없이 가입한 회원 누구나 쓸 수 있습니다. 그 밖의 프로그램은 그 프로그램을 구독했거나, 일반 등급 이상이면서 그 프로그램의 이용 기간이 남아 있을 때 쓸 수 있습니다(등급만으로는 열리지 않습니다). 지금 쓸 수 있는 프로그램은 대시보드의 「내 구독」에서 확인할 수 있습니다.'
where id = '993b75b1-17b0-481f-a4b8-c4c70fac7865';

insert into public.faq_items (category, sort_order, is_active, question, answer)
select v.category, v.sort_order, true, v.question, v.answer
from (values
  ('시작하기', 4, '핸드폰 번호를 꼭 등록해야 하나요?', '네. 핸드폰 번호(010 등)가 등록된 회원만 프로그램을 쓸 수 있습니다. 번호가 없으면 로그인할 때 입력 안내가 나오며, 저장하면 바로 이용할 수 있습니다. 일반 전화번호는 등록할 수 없습니다.'),
  ('저장공간 · 보관', 1, '제가 만든 글·이미지·영상은 얼마나 보관되나요?', '기본은 회원마다 500MB까지, 만든 날부터 30일 동안 보관한 뒤 자동으로 삭제됩니다. 블로그·SNS·유튜브에 발행한 자료도 똑같이 30일입니다. 오래 두고 쓸 자료는 삭제되기 전에 PC에 내려받아 두세요. 내가 만든 자료는 다른 회원에게 보이지 않습니다.'),
  ('저장공간 · 보관', 2, '저장공간이나 보관 기간을 늘릴 수 있나요?', '네. 「저장공간」 화면에서 저장 구독을 신청하면 용량과 보관 기간이 늘어납니다(현재 기준 라이트 1GB, 스탠다드 3GB, 프로 5GB — 발행한 자료는 만든 자료보다 더 오래 보관). 정확한 용량·기간·금액은 「저장공간」 화면의 요금제 카드에서 확인해 주세요. 구독이 끝나면 7일 유예 뒤 기본(500MB·30일)으로 돌아가며, 그때 30일이 지난 자료는 자동으로 정리됩니다.'),
  ('저장공간 · 보관', 3, '지금 얼마나 쓰고 있는지는 어디서 보나요?', '메인 사이트 「저장공간」 화면에서 전체 사용량과 프로그램별·종류별(이미지·영상·음악) 사용량을 볼 수 있습니다. 프로그램 화면의 💾 표시에서도 확인할 수 있고, 80%를 넘으면 안내가 나옵니다. 가득 차면 새로 저장하는 일이 제한될 수 있으니, 필요 없는 자료를 지우거나 저장 구독을 이용해 주세요.'),
  ('저장공간 · 보관', 4, '마켓(11번가 등)에 올린 상세페이지 사진도 지워지나요?', '대표 사진처럼 마켓이 자기 서버로 복사해 간 사진은 계속 보입니다. 다만 상세설명에 넣은 사진 중 우리 서버에서 불러오는 사진은 보관 기간이 지나거나 저장 구독이 끝나면 보이지 않게 됩니다. 오래 판매할 상품은 마켓 판매자 화면에서 사진을 직접 올려 두는 것이 안전합니다.')
) as v(category, sort_order, question, answer)
where not exists (select 1 from public.faq_items f where f.question = v.question);
